mapper.select:

where p.del_flag = '0'

    and (
        p.product_name like concat('%', #{keyword}, '%')
        or p.product_code like concat('%', #{keyword}, '%')
        or p.spec like concat('%', #{keyword}, '%')
    )

and p.product_name like concat('%', #{productName}, '%')
and p.product_code = #{productCode}
and p.sku like concat('%', #{sku}, '%')
and (p.category_id = #{categoryId} or find_in_set(#{categoryId}, c.ancestors))
and p.grade = #{grade}
and p.supplier_name like concat('%', #{supplierName}, '%')
and p.shop_dept_id = #{shopDeptId}
and p.status = #{status}
and p.shop_dept_id in #{deptId}
${params.dataScope}
order by p.create_time desc


where p.del_flag = '0'
  and p.supplier_name = #{supplierName}

    and p.shop_dept_id in

        #{deptId}


order by p.product_name asc, p.product_id asc


where p.del_flag = '0' and p.product_code = #{productCode}
and p.shop_dept_id = #{shopDeptId}
limit 1


where p.del_flag = '0'
  and p.category_id = #{categoryId}
  and p.product_name = #{productName}
  and ifnull(p.spec, '') = ifnull(#{spec}, '')
and p.shop_dept_id = #{shopDeptId}
limit 1
